-- universe-content.sql
-- Single source of truth for all keynor-core universe content data.
-- Generated by Siegmund on request. Applied manually by the user.
--
-- Target tables: maps, eras, map_eras, characters, character_categories,
--   places, place_categories, factions, faction_categories,
--   faction_members, items, item_categories, events, event_categories,
--   lore, lore_categories, entity_links, universe_entity_images,
--   archetypes, signs
--
-- Excluded: users, oauth2_* (environment-specific, never in scope)
--
-- ⚠  Destructive: TRUNCATE removes all existing universe content before reinserting.
-- ⚠  Apply only after Flyway migrations are fully up to date (V1–V16 at minimum).
-- ⚠  NOT idempotent — do not apply twice on the same database.
-- ⚠  Requires user authorization before execution. Agents never run this directly.
--
-- How to apply:
--   psql -U keynor -d keynor_core -f src/main/resources/db/seed/universe-content.sql
--
-- Last updated: 2026-07-22
-- Updated by:   Regenerated fresh from the live database (map pins feature,
--               PR keynor-core#80 / aniannoth-overview#63-64). Map changes:
--               DELETE the abstract "omniverse" map (its 2 map_eras rows
--               cascaded automatically, no separate map_eras statement
--               needed); INSERT a new NAVIGABLE map "primordial-map"
--               ("Primordial Era Map") with a real image, linked to the
--               same Primordial Era (EN + PT) omniverse previously
--               occupied — it is now the sole (and therefore default) map
--               for that era. No other universe content changed in this
--               update; places/events and their category tables remain
--               empty and are omitted, matching prior convention.
--
--               map_pins (new table, V16) is intentionally NOT in scope
--               for this dump yet — no pins have been created against it.
--               See .claude/skills/universe-content-dump.md for the
--               decision to leave it out for now.

-- ============================================================
-- TRUNCATE (join tables first, then parents, then root tables)
-- ============================================================

TRUNCATE
    universe_entity_images,
    entity_links,
    character_categories,
    place_categories,
    faction_categories,
    faction_members,
    item_categories,
    event_categories,
    lore_categories,
    characters, places, factions, items, events, lore,
    map_eras,
    eras,
    maps,
    signs,
    archetypes
CASCADE;

